  "pf-scholarship": {
    "starter": "#include <stdio.h>\n#include <string.h>\n#include <stdlib.h>\n\ntypedef struct{\n    char idNo[10];\n    char name[24];\n}StudentInfo;\n\ntypedef struct{\n    int math;\n    int science;\n    int english;\n}Scores;\n\ntypedef struct{\n    StudentInfo info;\n    Scores scores;\n}Applicant;\n\ntypedef struct{\n    Applicant* elemPtr;\n    int count;\n    int arrSize;\n}ListV3;\n\n// --- Function Prototypes ---\nvoid initListV3(ListV3* L, int size);\nint addApplicant(ListV3* L, Applicant a);\nvoid processApplicants(ListV3* L);\nvoid displayShortlist(ListV3 L);\nvoid freeListV3(ListV3* L);\n\nint main(void)\n{\n    // 1. Variable Declarations\n    ListV3 shortlist;\n    int slots;\n\n    // 2. Function Calls\n    printf(\"Number of interview slots: \");\n    scanf(\"%d\", &slots);\n\n    initListV3(&shortlist, slots);\n    if(shortlist.elemPtr == NULL){\n        printf(\"Unable to create the shortlist.\\n\");\n        return 1;\n    }\n\n    processApplicants(&shortlist);\n    displayShortlist(shortlist);\n\n    // 3. Cleanup\n    freeListV3(&shortlist);\n\n    return 0;\n}\n\n// --- Provided List Functions ---\nvoid initListV3(ListV3* L, int size)\n{\n    //Use the requested size; fall back to 1 if the size given is invalid.\n    if(size < 1){\n        size = 1;\n    }\n    L->elemPtr = malloc(sizeof(Applicant) * size);\n    L->count = 0;\n    L->arrSize = (L->elemPtr != NULL) ? size : 0;\n}\n\nvoid freeListV3(ListV3* L)\n{\n    free(L->elemPtr);\n    L->elemPtr = NULL;\n    L->count = 0;\n    L->arrSize = 0;\n}\n\n// --- Your Implementation ---\nint addApplicant(ListV3* L, Applicant a)\n{\n\n}\n\n// --- Input Function ---\nvoid processApplicants(ListV3* L)\n{\n    int n, i, result;\n    Applicant a;\n\n    printf(\"Number of applicants: \");\n    scanf(\"%d\", &n);\n\n    for(i = 0; i < n; i++){\n        printf(\"Applicant %d (ID Name Math Science English): \", i + 1);\n        scanf(\"%9s %23s %d %d %d\", a.info.idNo, a.info.name,\n              &a.scores.math, &a.scores.science, &a.scores.english);\n\n        result = addApplicant(L, a);\n        if(result == 1){\n            printf(\"%s (%s) added to the shortlist.\\n\", a.info.name, a.info.idNo);\n        } else if(result == 0){\n            printf(\"Shortlist is full. %s (%s) was not added.\\n\", a.info.name, a.info.idNo);\n        } else {\n            printf(\"%s is already on the shortlist.\\n\", a.info.idNo);\n        }\n    }\n}\n\n// --- Display Function ---\nvoid displayShortlist(ListV3 L)\n{\n    int i;\n    if(L.count == 0){\n        printf(\"\\nThe shortlist is empty.\\n\");\n        return;\n    }\n\n    printf(\"\\n=== INTERVIEW SHORTLIST (%d/%d) ===\\n\", L.count, L.arrSize);\n    for(i = 0; i < L.count; i++){\n        printf(\"%d. [%s] %s - Math %d, Science %d, English %d = %d\\n\", i + 1,\n               L.elemPtr[i].info.idNo, L.elemPtr[i].info.name,\n               L.elemPtr[i].scores.math, L.elemPtr[i].scores.science, L.elemPtr[i].scores.english,\n               L.elemPtr[i].scores.math + L.elemPtr[i].scores.science + L.elemPtr[i].scores.english);\n    }\n}\n",
    "code": "#include <stdio.h>\n#include <string.h>\n#include <stdlib.h>\n\ntypedef struct{\n    char idNo[10];\n    char name[24];\n}StudentInfo;\n\ntypedef struct{\n    int math;\n    int science;\n    int english;\n}Scores;\n\ntypedef struct{\n    StudentInfo info;\n    Scores scores;\n}Applicant;\n\ntypedef struct{\n    Applicant* elemPtr;\n    int count;\n    int arrSize;\n}ListV3;\n\n// --- Function Prototypes ---\nvoid initListV3(ListV3* L, int size);\nint addApplicant(ListV3* L, Applicant a);\nvoid processApplicants(ListV3* L);\nvoid displayShortlist(ListV3 L);\nvoid freeListV3(ListV3* L);\n\nint main(void)\n{\n    // 1. Variable Declarations\n    ListV3 shortlist;\n    int slots;\n\n    // 2. Function Calls\n    printf(\"Number of interview slots: \");\n    scanf(\"%d\", &slots);\n\n    initListV3(&shortlist, slots);\n    if(shortlist.elemPtr == NULL){\n        printf(\"Unable to create the shortlist.\\n\");\n        return 1;\n    }\n\n    processApplicants(&shortlist);\n    displayShortlist(shortlist);\n\n    // 3. Cleanup\n    freeListV3(&shortlist);\n\n    return 0;\n}\n\n// --- Provided List Functions ---\nvoid initListV3(ListV3* L, int size)\n{\n    //Use the requested size; fall back to 1 if the size given is invalid.\n    if(size < 1){\n        size = 1;\n    }\n    L->elemPtr = malloc(sizeof(Applicant) * size);\n    L->count = 0;\n    L->arrSize = (L->elemPtr != NULL) ? size : 0;\n}\n\nvoid freeListV3(ListV3* L)\n{\n    free(L->elemPtr);\n    L->elemPtr = NULL;\n    L->count = 0;\n    L->arrSize = 0;\n}\n\n// --- Your Implementation ---\nint addApplicant(ListV3* L, Applicant a)\n{\n    int i, total, result = -1;\n\n    /* stops at the applicant with the same ID number, or at the end of the list */\n    for(i = 0; i < L->count && strcmp(L->elemPtr[i].info.idNo, a.info.idNo) != 0; i++){}\n\n    if(i == L->count){                      /* not on the shortlist yet */\n        result = 0;\n        //Check if there is enough space to insert.\n        if(L->count < L->arrSize){\n            total = a.scores.math + a.scores.science + a.scores.english;\n            //Find the correct index for insertion: after every total at least as high.\n            for(i = 0; i < L->count && L->elemPtr[i].scores.math + L->elemPtr[i].scores.science\n                                       + L->elemPtr[i].scores.english >= total; i++){}\n\n            //Shift elements down.\n            if(i < L->count){\n                memmove(L->elemPtr+i+1, L->elemPtr+i, sizeof(Applicant) * (L->count-i));\n            }\n            //Insert.\n            L->elemPtr[i] = a;\n            L->count++;\n            result = 1;\n        }\n    }\n\n    return result;\n}\n\n// --- Input Function ---\nvoid processApplicants(ListV3* L)\n{\n    int n, i, result;\n    Applicant a;\n\n    printf(\"Number of applicants: \");\n    scanf(\"%d\", &n);\n\n    for(i = 0; i < n; i++){\n        printf(\"Applicant %d (ID Name Math Science English): \", i + 1);\n        scanf(\"%9s %23s %d %d %d\", a.info.idNo, a.info.name,\n              &a.scores.math, &a.scores.science, &a.scores.english);\n\n        result = addApplicant(L, a);\n        if(result == 1){\n            printf(\"%s (%s) added to the shortlist.\\n\", a.info.name, a.info.idNo);\n        } else if(result == 0){\n            printf(\"Shortlist is full. %s (%s) was not added.\\n\", a.info.name, a.info.idNo);\n        } else {\n            printf(\"%s is already on the shortlist.\\n\", a.info.idNo);\n        }\n    }\n}\n\n// --- Display Function ---\nvoid displayShortlist(ListV3 L)\n{\n    int i;\n    if(L.count == 0){\n        printf(\"\\nThe shortlist is empty.\\n\");\n        return;\n    }\n\n    printf(\"\\n=== INTERVIEW SHORTLIST (%d/%d) ===\\n\", L.count, L.arrSize);\n    for(i = 0; i < L.count; i++){\n        printf(\"%d. [%s] %s - Math %d, Science %d, English %d = %d\\n\", i + 1,\n               L.elemPtr[i].info.idNo, L.elemPtr[i].info.name,\n               L.elemPtr[i].scores.math, L.elemPtr[i].scores.science, L.elemPtr[i].scores.english,\n               L.elemPtr[i].scores.math + L.elemPtr[i].scores.science + L.elemPtr[i].scores.english);\n    }\n}\n"
  }
